import{_ as a}from"./chunks/holybro_sik_radio.li0FOsNE.js";import{_ as r,o,c as t,al as i}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"SiK Radio","description":"","frontmatter":{},"headers":[],"relativePath":"en/telemetry/sik_radio.md","filePath":"en/telemetry/sik_radio.md"}'),n={name:"en/telemetry/sik_radio.md"};function d(s,e,l,c,h,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="sik-radio" tabindex="-1">SiK Radio <a class="header-anchor" href="#sik-radio" aria-label="Permalink to &quot;SiK Radio&quot;">​</a></h1><p><a href="https://github.com/LorenzMeier/SiK" target="_blank" rel="noreferrer">SiK radio</a> is a collection of firmware and tools for telemetry radios.</p><p>PX4 is protocol-compatible with radios that use <em>SiK</em>. SiK Radios often come with appropriate connectors/cables allowing them to be directly connected to <a href="./../flight_controller/pixhawk_series">Pixhawk Series</a> controllers (in some cases you may need to obtain an appropriate cable/connector). Typically you will need a pair of devices - one for the vehicle and one for the ground station.</p><p>Hardware for the SiK radio can be obtained from various manufacturers/stores in variants that support different range and form factors.</p><p><img src="'+a+'" alt="SiK Radio"></p><h2 id="vendors" tabindex="-1">Vendors <a class="header-anchor" href="#vendors" aria-label="Permalink to &quot;Vendors&quot;">​</a></h2><ul><li><a href="./../telemetry/holybro_sik_radio">Holybro Telemetry Radio</a></li><li><a href="./../telemetry/holybro_sik_longrange">HolyBro SiK Long Range</a></li><li><a href="./../telemetry/rfd900_telemetry">RFD900 Telemetry Radio</a></li><li><a href="./../telemetry/tfsik_telemetry">ThunderFly TFSIK01 Telemetry Radio</a></li><li><del><em>HKPilot Telemetry Radio</em></del> (Discontinued)</li><li><del><em>3DR Telemetry Radio</em></del> (Discontinued)</li></ul><h2 id="setup-configuration" tabindex="-1">Setup/Configuration <a class="header-anchor" href="#setup-configuration" aria-label="Permalink to &quot;Setup/Configuration&quot;">​</a></h2><p>The ground station-based radio is connected via USB (essentially plug-n-play).</p><p>The vehicle-based radio is connected to the flight-controller&#39;s <code>TELEM1</code> port, and typically requires no further configuration.</p><h2 id="link-throughput" tabindex="-1">Link Throughput <a class="header-anchor" href="#link-throughput" aria-label="Permalink to &quot;Link Throughput&quot;">​</a></h2><p>The serial baudrate says little about what a SiK link carries over the air. At 57600 baud with the common 64 kbps air rate, a radio carries roughly 2000 B/s with error correction enabled and about twice that without.</p><p><a href="./../advanced_config/parameter_reference#MAV_0_RATE">MAV_0_RATE</a> caps what PX4 sends on <code>TELEM1</code>. Setting it above what the link carries does not make telemetry faster: the radio drops packets instead, which shows up as MAVLink loss and makes parameter and log downloads slow or unreliable. Lower it if you see loss.</p><p>Two AT commands report the radio&#39;s own limits: <code>ATI5</code> lists the settings, including <code>S2:AIR_SPEED</code> and <code>S5:ECC</code>, and <code>ATI6</code> reports <code>max_data_packet_length</code> - the largest MAVLink packet the radio sends in one piece. Error correction roughly halves both the throughput and that packet size.</p><h2 id="firmware-update" tabindex="-1">Firmware Update <a class="header-anchor" href="#firmware-update" aria-label="Permalink to &quot;Firmware Update&quot;">​</a></h2><p>Hardware sourced from most <a href="#vendors">vendors</a> should come pre-configured with the latest firmware. You may need to update older hardware with new firmware, for example to gain support for MAVLink 2.</p><p>You can update the radio firmware using <em>QGroundControl</em>: <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/firmware.html" target="_blank" rel="noreferrer">QGroundControl User Guide &gt; Loading Firmware</a>.</p><h2 id="advanced-setup-configuration" tabindex="-1">Advanced Setup/Configuration <a class="header-anchor" href="#advanced-setup-configuration" aria-label="Permalink to &quot;Advanced Setup/Configuration&quot;">​</a></h2><p>The Development section has <a href="./../data_links/sik_radio">additional information</a> about building firmware and AT-command based configuration. This should not be required by non-developers.</p>',19)])])}const _=r(n,[["render",d]]);export{f as __pageData,_ as default};
